props.code:
# 示例1：匹配单个域名
server {
    listen 80;
    server_name example.com;  # 仅匹配 example.com
    root /var/www/example;
}

# 示例2：匹配多个域名
server {
    listen 80;
    server_name example.com www.example.com;  # 同时匹配带www和不带www的域名
    root /var/www/example;
}

# 示例3：使用通配符
server {
    listen 80;
    server_name *.example.com;  # 匹配所有子域名（如 blog.example.com）
    root /var/www/subdomains;
}

# 示例4：使用正则表达式
server {
    listen 80;
    server_name ~^(.*)\.example\.com$;  # 正则匹配，$1 可在配置中引用
    root /var/www/$1;
}

# 示例5：默认服务器
server {
    listen 80 default_server;  # 所有未匹配的请求都会路由到这里
    server_name _;  # 使用下划线作为占位符
    return 444;  # 直接关闭连接或返回自定义错误页
}

server {
    listen 80;
    server_name site1.com;
    root /var/www/site1;
}

server {
    listen 80;
    server_name site2.com;
    root /var/www/site2;
}

server {
    listen 80;
    server_name example.com;
    return 301 http://www.example.com$request_uri;
}

server {
    listen 80;
    server_name www.example.com;
    root /var/www/example;
}

server {
    listen 80;
    server_name api.example.com;
    proxy_pass http://backend_api;
}

server {
    listen 80;
    server_name blog.example.com;
    root /var/www/blog;
}

http {
    # 基本设置
    include       mime.types;
    default_type  application/octet-stream;
    sendfile      on;
    keepalive_timeout  65;

    # 日志设置
    access_log  /var/log/nginx/access.log;
    error_log   /var/log/nginx/error.log;

    # Gzip压缩
    gzip  on;
    gzip_types text/plain text/css application/json application/javascript;

    # 虚拟主机配置
    server {
        listen       80;
        server_name  example.com;
        root         /var/www/html;

        # 访问控制
        location /admin/ {
            auth_basic           "Admin Area";
            auth_basic_user_file /etc/nginx/.htpasswd;
        }

        # 默认首页
        index index.html index.htm;

        # 错误页面
        error_page 500 502 503 504 /50x.html;
        location = /50x.html {
            root /var/www/error_pages;
        }
    }
}

server {
    listen 80;
    server_name api.example.com;

    location / {
        proxy_pass http://backend_server:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # 超时设置
        proxy_connect_timeout 30s;
        proxy_send_timeout    60s;
        proxy_read_timeout    60s;

        # 缓冲区设置
        proxy_buffer_size          128k;
        proxy_buffers              4 256k;
        proxy_busy_buffers_size    256k;
    }
}

http {
    # 负载均衡组
    upstream backend_servers {
        # 轮询策略（默认）
        server backend1.example.com weight=5;
        server backend2.example.com weight=3;
        server backend3.example.com backup;  # 备用服务器

        # IP哈希策略（保证同一客户端请求到同一服务器）
        # ip_hash;

        # 最少连接策略
        # least_conn;
    }

    server {
        listen 80;
        server_name loadbalancer.example.com;

        location / {
            proxy_pass http://backend_servers;
            proxy_http_version 1.1;
            proxy_set_header Connection "";  # 启用HTTP/1.1的keepalive
        }
    }
}

server {
    listen 80;
    server_name static.example.com;

    location /static/ {
        root /data/www;
        expires 30d;  # 静态资源缓存30天
        add_header Cache-Control "public";

        # 禁用日志以提高性能
        access_log off;
        log_not_found off;
    }

    # 大文件下载优化
    location /download/ {
        sendfile on;
        sendfile_max_chunk 1m;  # 防止worker进程阻塞
        tcp_nopush on;
    }
}

server {
    listen 80;
    server_name example.com;
    return 301 https://$host$request_uri;  # HTTP重定向到HTTPS
}

server {
    listen 443 ssl http2;
    server_name example.com;

    # SSL证书配置
    ssl_certificate      /etc/nginx/ssl/cert.pem;
    ssl_certificate_key  /etc/nginx/ssl/key.pem;

    # SSL优化
    ssl_protocols TLSv1.3 TLSv1.2;  # 仅支持现代TLS协议
    ssl_prefer_server_ciphers on;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;

    # HSTS头部（强制HTTPS）
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    # OCSP Stapling
    ssl_stapling on;
    ssl_stapling_verify on;
    resolver 8.8.8.8 8.8.4.4 valid=300s;
}

http {
    # 定义缓存区域
    proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=my_cache:10m max_size=10g inactive=60m use_temp_path=off;

    server {
        listen 80;
        server_name cache.example.com;

        location / {
            proxy_pass http://backend;
            proxy_cache my_cache;  # 使用上面定义的缓存区域

            # 缓存策略
            proxy_cache_valid 200 302 10m;  # 成功响应缓存10分钟
            proxy_cache_valid 404      1m;  # 404缓存1分钟

            # 缓存键设置
            proxy_cache_key "$scheme$request_method$host$request_uri";

            # 缓存穿透控制
            proxy_cache_min_uses 3;  # 请求3次后才缓存
            proxy_no_cache $cookie_auth;  # 带认证cookie的请求不缓存
        }
    }
}

http {
    # 定义限流区域
    limit_req_zone $binary_remote_addr zone=mylimit:10m rate=10r/s;

    server {
        listen 80;

        location /api/ {
            # 突发请求处理
            limit_req zone=mylimit burst=20 nodelay;

            # 连接数限制
            limit_conn perip 5;  # 每个IP最多5个并发连接
            limit_conn perserver 100;  # 服务器总并发连接数限制

            # 带宽限制
            limit_rate 100k;  # 限制下载速度为100KB/s
        }
    }
}

server {
    listen 80;
    server_name example.com;

    # 移除尾部斜杠
    rewrite ^/(.*)/$ /$1 permanent;

    # 旧URL跳转
    rewrite ^/old-path/(.*)$ /new-path/$1 redirect;

    # 根据参数跳转
    if ($args ~* "id=(\d+)") {
        return 301 /item/$1;
    }

    # 基于目录的跳转
    location /blog/ {
        rewrite ^/blog/(.*)$ https://blog.example.com/$1 permanent;
    }
}

server {
    listen 80;

    location /ws/ {
        proxy_pass http://websocket_backend;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "Upgrade";
        proxy_set_header Host $host;

        # 防止WebSocket连接超时
        proxy_read_timeout 86400;
    }
}

server {
    listen 80;

    location ~* \.(jpg|jpeg|png|gif|pdf)$ {
        valid_referers none blocked example.com *.example.com;

        if ($invalid_referer) {
            return 403;
            # 或者重定向到防盗链图片
            # rewrite ^/ http://example.com/forbidden.png;
        }
    }
}
